chunk:
ProductVariant:
  type: object
  description: A variant of the base product distinguished by region, edition, or version
  properties:
    variantId:   { type: string }
    variantKey:  { type: string, description: "Discriminator value (e.g. state code, edition label)", example: "CA" }
    label:       { type: string, description: "Human-readable variant label", example: "California Edition" }
    externalIds:
      type: object
      properties:
        isbn:               { type: string, description: "ISBN-13 for this variant" }
        quickbooksItemId:   { type: string }
        salesforceProduct2Id: { type: string }
    inventory:
      type: object
      properties:
        quantityOnHand:    { type: integer }
        quantityCommitted: { type: integer }
        quantityAvailable: { type: integer }

Timestamps:
  type: object
  properties:
    createdAt:   { type: string, format: date-time }
    updatedAt:   { type: string, format: date-time }
    discontinuedAt: { type: string, format: date-time }
